user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning explains why an observed failure or unexpected result occurred by identifying a specific causal defect in an assumption, interpretation, or implementation, rather than merely restating the error.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The agent text that attributes the observed failure to an identifiable cause."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to a failure or unexpected result and states a concrete cause for it.",
      "The stated cause is specific enough to imply what must change for the failure to be resolved."
    ],
    "exclusion_conditions": [
      "The reasoning only repeats or paraphrases the error message without explaining its cause.",
      "The reasoning reports the failure without any causal attribution."
    ]
  },
  {
    "name": "REVISES_INTERPRETATION_UNDER_CONTRADICTING_OBSERVATION",
    "definition": "The reasoning abandons or corrects a prior working interpretation because the observation reports values that are inconsistent with that interpretation, and it adopts a revised interpretation consistent with the observed values.",
    "parameters": [
      {
        "name": "revision_reasoning",
        "type": "reasoning",
        "description": "The agent text recognizing the contradiction and stating the corrected interpretation."
      },
      {
        "name": "contradicting_observation",
        "type": "observation",
        "description": "The observation whose reported content conflicts with the prior expectation."
      }
    ],
    "assertion_conditions": [
      "The observation contains concrete content that does not match the interpretation the agent had been operating under.",
      "The reasoning explicitly notes the mismatch and states a replacement interpretation that fits the observed content."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates the observation without revising any prior interpretation.",
      "The observation is consistent with the prior interpretation, so no revision is warranted."
    ]
  },
  {
    "name": "RESOLVES_AMBIGUOUS_TERM_WITH_DOCUMENTED_EVIDENCE",
    "definition": "The reasoning maps an ambiguous or undefined term from the task onto concrete data categories by citing structural or provenance information found in retrieved documentation, thereby producing an operational definition that can be applied to the data.",
    "parameters": [
      {
        "name": "interpretation_reasoning",
        "type": "reasoning",
        "description": "The agent text that defines the ambiguous term in terms of concrete categories."
      },
      {
        "name": "documentation_observation",
        "type": "observation",
        "description": "The observation containing the documentation whose described structure or provenance supports the mapping."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a term whose meaning is not directly represented in the data.",
      "The reasoning cites identifiable content of the documentation (described sources, categories, or column semantics) as the basis for the concrete mapping."
    ],
    "exclusion_conditions": [
      "The reasoning guesses the mapping without referring to any documented evidence.",
      "The reasoning only summarizes the documentation without deriving an operational definition from it."
    ]
  },
  {
    "name": "MEASURES_BEHAVIOR_TO_RULE_OUT_RESULT_AMBIGUITY",
    "definition": "A targeted measurement of tool or library behavior is performed to determine whether a suspected hidden effect (such as implicit defaults or added elements) would change a computed result, and the observed behavior settles whether the result is affected.",
    "parameters": [
      {
        "name": "measurement_action",
        "type": "action",
        "description": "The action that directly exercises the tool or library to expose its behavior."
      },
      {
        "name": "ambiguity_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the suspected effect and its potential impact on the result."
      },
      {
        "name": "behavior_observation",
        "type": "observation",
        "description": "The observation reporting the measured behavior relevant to the suspected effect."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a specific mechanism that could alter the computed quantity, together with its possible magnitude or direction.",
      "The action is designed to expose exactly that mechanism rather than to produce the primary result.",
      "The observation reports behavior that determines whether the suspected effect is present."
    ],
    "exclusion_conditions": [
      "The action is part of the main computation rather than a targeted check of tool behavior.",
      "The observation does not report behavior bearing on the suspected effect.",
      "No identifiable suspected effect motivates the measurement."
    ]
  },
  {
    "name": "AMENDS_ARTIFACT_TO_ADDRESS_DIAGNOSED_CAUSE",
    "definition": "A modification action rewrites or adjusts a previously created artifact in a way that specifically addresses the cause identified in a failure diagnosis, rather than making an unrelated change.",
    "parameters": [
      {
        "name": "amendment_action",
        "type": "action",
        "description": "The action that rewrites or adjusts the existing artifact."
      },
      {
        "name": "cause_reasoning",
        "type": "reasoning",
        "description": "The reasoning that identified the cause of the prior failure and implies the needed change."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the failure or unexpected result that motivated the amendment."
      }
    ],
    "assertion_conditions": [
      "A prior observation reports an unsuccessful or unexpected outcome of the artifact under revision.",
      "The reasoning attributes that outcome to an identifiable cause.",
      "The amendment action changes the artifact's content in a way that removes that cause."
    ],
    "exclusion_conditions": [
      "The action creates a new artifact unrelated to any diagnosed failure.",
      "The action modifies the artifact without any identified failure or cause connecting the change to the previous outcome.",
      "The change targets a different part of the artifact than the diagnosed cause."
    ]
  },
  {
    "name": "CONFIRMS_RESULT_BY_INDEPENDENT_RECOMPUTATION",
    "definition": "A verification action re-derives an already computed quantity through a different loading or processing path, and the resulting observation reports a value identical to the earlier one, allowing the reasoning to treat the result as confirmed rather than merely attempted.",
    "parameters": [
      {
        "name": "recomputation_action",
        "type": "action",
        "description": "The action that re-derives the quantity using an alternative implementation path."
      },
      {
        "name": "agreement_observation",
        "type": "observation",
        "description": "The observation reporting the recomputed quantity and its agreement with the earlier value."
      },
      {
        "name": "confirmation_reasoning",
        "type": "reasoning",
        "description": "The agent text comparing the two derivations and concluding agreement."
      }
    ],
    "assertion_conditions": [
      "The action uses a materially different path than the original computation for the same quantity.",
      "The observation reports a value that matches the earlier result.",
      "The reasoning explicitly states that the two derivations agree and that the result is therefore corroborated."
    ],
    "exclusion_conditions": [
      "The action repeats the original computation unchanged, providing no independent path.",
      "The observed values differ, or the discrepancy is not addressed.",
      "The reasoning does not draw any conclusion from the comparison."
    ]
  },
  {
    "name": "VERIFIES_DELIVERED_OUTPUT_CONTENT",
    "definition": "The reasoning confirms the final deliverable by checking that the content reported by an inspection observation of the output artifact matches the intended answer, distinguishing a confirmed delivery from an assumed one.",
    "parameters": [
      {
        "name": "verification_reasoning",
        "type": "reasoning",
        "description": "The agent text confirming that the inspected artifact content is the intended final output."
      },
      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation reporting the actual content or metadata of the delivered artifact."
      }
    ],
    "assertion_conditions": [
      "The observation reports the concrete content or file state of the artifact intended as the final deliverable.",
      "The reasoning states that this content corresponds to the intended answer or result."
    ],
    "exclusion_conditions": [
      "The artifact is not the final deliverable, only an intermediate file.",
      "The observation does not expose the artifact's content, so no content match can be established.",
      "The reasoning does not draw any confirmation from the observation."
    ]
  },
  {
    "name": "SUMMARIZES_COMPLETED_WORK",
    "definition": "The reasoning consolidates the interpretation decisions, the performed computations, and the obtained result into a retrospective account of what was done and why, rather than proposing new future actions.",
    "parameters": [
      {
        "name": "summary_reasoning",
        "type": "reasoning",
        "description": "The agent text recapitulating the completed work and its result."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to actions or observations already completed, not to future steps as its main content.",
      "The reasoning restates the key decisions and the final result in a consolidated form."
    ],
    "exclusion_conditions": [
      "The reasoning only announces intended future actions.",
      "The reasoning is a single-step remark without consolidation of prior decisions and outcomes."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or a sequence of intended future actions that the agent commits to performing.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action.",
      "The intended action is presented as something the agent will do next, rather than as a mere possibility or a restatement of the task."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions already completed.",
      "The reasoning only restates task requirements without committing to a future action."
    ]
  },
  {
    "name": "SPECIFIES_CORRECTIVE_CONTENT_WITH_JUSTIFICATION",
    "definition": "The reasoning supplies concrete content intended to correct, complete, or otherwise modify an artifact and justifies why that content satisfies the target requirement, optionally by evaluating and rejecting an alternative that would fail.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that states the concrete replacement or completion content and the justification for its correctness."
      }
    ],
    "assertion_conditions": [
      "The reasoning states concrete content to be applied to the artifact, such as specific steps, replacement text, or a proof script, not merely the intention to change it.",
      "The reasoning explains why the stated content achieves the goal, using the semantics of the relevant domain entities.",
      "If alternative candidates are considered, at least one is rejected for an identified reason."
    ],
    "exclusion_conditions": [
      "The reasoning only describes the defect or goal without supplying concrete content to apply.",
      "The reasoning only lists generic strategies without indicating which one will be used or why it works."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion using identifiable content of the observation as supporting evidence for that conclusion.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the evidence-based conclusion."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the evidence used for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion that goes beyond restating the observation, such as a judgment about correctness, availability, or completion.",
      "Identifiable content of the observation, such as values, listed artifacts, returned text, or computed output, is used as support for that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or summarizes the observation without drawing a conclusion from it.",
      "The observation is unrelated to the conclusion or contains nothing that supports it."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_AND_PRESCRIBES_CORRECTION",
    "definition": "An observation reports a failed or unusable outcome of an attempted approach; the reasoning identifies a specific cause, constraint, or limitation of that approach and prescribes a corrective approach that differs in the diagnosed respect; and the corrective action executes that different approach.",
    "parameters": [
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the error, failure, or unsuccessful or unusable outcome."
      },
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning explaining the cause, constraint, or limitation of the failed approach and specifying the corrected approach."
      },
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The action that applies the corrected approach prescribed by the diagnosis."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, failure, or result that cannot satisfy the intended purpose.",
      "The reasoning states a specific cause, constraint, or limitation of the attempted approach rather than merely noting that it failed.",
      "The reasoning specifies how the approach must change in light of that cause, constraint, or limitation.",
      "The corrective action implements a materially different method, route, or operation that is distinguishable from the failed action."
    ],
    "exclusion_conditions": [
      "No failure or unusable outcome is evidenced.",
      "The reasoning retries the same operation without identifying a cause, constraint, or limitation or changing the approach.",
      "The reasoning speculates about causes unrelated to the reported error.",
      "The corrective action does not reflect the stated diagnosis or does not differ from the failed approach in the diagnosed respect."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action queries the environment to resolve a specific uncertainty or unverified prerequisite identified in reasoning, and the resulting observation provides evidence that settles or materially informs it before dependent work proceeds.",
    "parameters": [
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the uncertainty or prerequisite that must be settled."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted query about that uncertainty."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the result relevant to the uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific open question or prerequisite condition whose value is not yet known.",
      "The probe action is directed at obtaining exactly that information from the environment.",
      "The observation returns information that resolves or materially informs the identified question."
    ],
    "exclusion_conditions": [
      "No identifiable uncertainty or prerequisite motivates the action.",
      "The action is unrelated to the stated question, or the observation does not address it.",
      "The probe merely repeats information already established earlier in the trajectory."
    ]
  },
  {
    "name": "VERIFIES_REQUIREMENT_SATISFACTION",
    "definition": "After an outcome has been produced, a separate verification action inspects the produced artifact or result, its observation demonstrates the required property directly rather than only the absence of errors, and the reasoning concludes from it that the requirement is satisfied.",
    "parameters": [
      {
        "name": "verification_action",
        "type": "action",
        "description": "The action that inspects or exercises the already produced outcome."
      },
      {
        "name": "verification_observation",
        "type": "observation",
        "description": "The observation containing content that demonstrates the required property."
      },
      {
        "name": "concluding_reasoning",
        "type": "reasoning",
        "description": "The reasoning concluding that the requirement is met on the basis of that observation."
      }
    ],
    "assertion_conditions": [
      "The verification action is distinct from the action that produced the outcome and targets the produced artifact or result.",
      "The observation exposes content showing the required property actually holds, for example the resulting object is present and carries the expected content.",
      "The reasoning explicitly concludes that the requirement is satisfied, citing that observation."
    ],
    "exclusion_conditions": [
      "The action is the one that produced the outcome rather than an independent check of it.",
      "The observation only indicates that no error occurred, without demonstrating the required property.",
      "No conclusion is drawn from the observation, or the conclusion is not tied to it."
    ]
  },
  {
    "name": "ENUMERATES_REQUIRED_COMPONENTS",
    "definition": "The reasoning decomposes a stated goal into multiple distinct prerequisite entities, capabilities, permissions, artifacts, or state conditions that must exist or hold for the goal to be satisfiable, turning the goal description into identifiable obligations.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text listing the prerequisite entities, capabilities, permissions, artifacts, or state conditions that must exist or hold for the stated goal to be satisfiable."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies multiple distinct elements that must exist, be configured, or hold, such as entities, capabilities, permissions, artifacts, or state conditions.",
      "Each identified element is justified by the goal's expected usage or by an explicit dependency of the goal rather than being listed arbitrarily.",
      "The enumeration includes required state, artifacts, or configuration obligations beyond merely ordering actions to perform."
    ],
    "exclusion_conditions": [
      "The reasoning only restates the goal without identifying required elements.",
      "The reasoning only gives an ordered procedure or action plan without identifying what must exist or hold.",
      "The reasoning proposes only a single required element or an incidental detail."
    ]
  },
  {
    "name": "IMPLEMENTS_PLANNED_STEP",
    "definition": "The action carries out a concrete operation or creates/configures an artifact that the reasoning explicitly identified as an intended step, so the action is the observable execution of a previously stated intention.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the intended step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning that explicitly states the intended step which the action executes."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly names the operation or artifact that the action then operates on before that action occurs.",
      "The action's content matches the intended step in purpose and target, not merely in topic.",
      "The action executes that intended step rather than an unrelated exploration."
    ],
    "exclusion_conditions": [
      "The action explores the environment without a corresponding previously stated intention.",
      "The reasoning mentions the operation or artifact only after the action's result is known.",
      "The action's target or purpose differs from the stated intention."
    ]
  },
  {
    "name": "ANTICIPATES_PROCEDURAL_PITFALL",
    "definition": "The reasoning predicts a specific failure mode or unusable outcome that would arise from a default or naive procedure and states a preventive or corrective configuration measure derived from that prediction.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that predicts the failure mode and states the preventive or corrective measure."
      }
    ],
    "assertion_conditions": [
      "The reasoning describes a concrete way the default or planned procedure could fail or produce an unusable result.",
      "The reasoning links that predicted failure to a preventive or corrective measure that changes the procedure or configuration.",
      "The predicted failure is prospective rather than an already observed error."
    ],
    "exclusion_conditions": [
      "The reasoning observes a failure that has already occurred rather than predicting one.",
      "The reasoning lists general best practices without linking them to an identified failure mode.",
      "The reasoning predicts a failure but does not state any measure addressing it."
    ]
  },
  {
    "name": "VALIDATES_BEFORE_ACTIVATION",
    "definition": "A single action applies or activates a candidate configuration, input, or state change only after an explicit validity check of that candidate within the same invocation, and the observation reports both the successful validation and the resulting applied or active state.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that performs the validity check and then applies or activates the candidate configuration, input, or state change."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result reporting the validation outcome and the resulting applied or active state."
      }
    ],
    "assertion_conditions": [
      "The action includes an explicit validation of the candidate before applying or activating it.",
      "Application or activation is conditioned on that validation succeeding within the same invocation.",
      "The observation reports the validation as successful and shows the candidate applied or the target active."
    ],
    "exclusion_conditions": [
      "The candidate is applied or activated without any preceding validation.",
      "Validation is performed but application or activation does not follow.",
      "The observation shows a validation failure or no evidence that the candidate was applied or the target is active.",
      "Validation and application occur in separate invocations, or the validation concerns an unrelated candidate."
    ]
  },
  {
    "name": "SIMULATES_END_USER_WORKFLOW",
    "definition": "The action reproduces the operation sequence that an external consumer or end user would perform against the assembled system, using disposable or scratch artifacts, in order to validate the system as it will be experienced by that consumer rather than to produce the final deliverable state.",
    "parameters": [
      {
        "name": "simulating_action",
        "type": "action",
        "description": "The tool invocation that executes the reproduced consumer-side operation sequence."
      },
      {
        "name": "consumer_perspective_reasoning",
        "type": "reasoning",
        "description": "Reasoning that frames the upcoming operation as acting like the external consumer or end user and explains that the sequence is a simulation for validation."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the upcoming operation as what an external consumer or end user would do against the system.",
      "The action performs a multi-step sequence matching that consumer behavior, distinct from the construction or configuration steps that constitute the deliverable.",
      "The action relies on disposable or scratch artifacts, so the simulation does not itself become part of the final state.",
      "The stated purpose is to exercise the system as a consumer would, not to build the deliverable."
    ],
    "exclusion_conditions": [
      "The action is an ordinary construction or configuration step that constitutes the deliverable itself.",
      "The action is a single isolated probe of one component rather than the consumer-visible operation sequence.",
      "The reasoning does not connect the action to consumer-side behavior.",
      "The action is not executed with disposable or scratch artifacts and therefore permanently alters the delivered state."
    ]
  },
  {
    "name": "OBSERVATION_CONFIRMS_EXPECTED_OUTCOME",
    "definition": "The observation reports exactly the result that the reasoning had predicted or required before the result was obtained, so the previously stated expectation can be judged satisfied rather than merely error-free.",
    "parameters": [
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "Reasoning stating the concrete expected or required outcome before the result is inspected."
      },
      {
        "name": "confirming_observation",
        "type": "observation",
        "description": "The tool result whose content corresponds to that expected outcome."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a concrete expected outcome (a value, response, or state) before the corresponding observation is available.",
      "The observation contains content corresponding to that expectation, allowing the expectation to be judged satisfied rather than merely free of errors."
    ],
    "exclusion_conditions": [
      "The reasoning states no expected outcome, so the result cannot be judged against an expectation.",
      "The observation reports a different or partial result than the one expected.",
      "The observation is unrelated to the expectation expressed in the reasoning.",
      "The expectation is formulated only after the result has already been observed."
    ]
  },
  {
    "name": "RECOGNIZES_INCONCLUSIVE_TOOL_RESULT",
    "definition": "The reasoning determines that an observation, although not reported as an error, fails to answer the question it was meant to answer because of a limitation of the method or tool used, and specifies a different method intended to obtain the missing information.",
    "parameters": [
      {
        "name": "reassessment_reasoning",
        "type": "reasoning",
        "description": "Reasoning that identifies the inadequacy of the earlier result, attributes it to a method limitation, and specifies an alternative method."
      },
      {
        "name": "uninformative_observation",
        "type": "observation",
        "description": "The observation whose output is empty, truncated, or otherwise uninformative for the intended question without being flagged as an error."
      }
    ],
    "assertion_conditions": [
      "The observation returned output that does not answer the intended question, and the observation is not flagged as an error.",
      "The reasoning attributes the missing information to a limitation of the command, tool, or method form used.",
      "The reasoning specifies a different command, option, or method intended to produce the missing information."
    ],
    "exclusion_conditions": [
      "The observation answers the question adequately, so no replacement method is needed.",
      "The observation reports an explicit failure that is diagnosed as a defect cause rather than a method limitation.",
      "The reasoning retries the identical method without changing it.",
      "The reasoning only notes that the output is empty without attributing it to a method limitation or proposing an alternative."
    ]
  },
  {
    "name": "RESTORES_PRISTINE_STATE_AFTER_TEST",
    "definition": "Following verification or test activity, the agent deliberately removes or resets the artifacts created by that activity so the system returns to the state a later consumer expects to encounter before any such activity occurred.",
    "parameters": [
      {
        "name": "cleanup_reasoning",
        "type": "reasoning",
        "description": "Reasoning that enumerates the artifacts created during verification and states the target initial state to restore."
      },
      {
        "name": "cleanup_actions",
        "type": "action[]",
        "description": "The actions that delete, reset, or purge those artifacts; collectively they restore the pre-test state."
      },
      {
        "name": "state_observation",
        "type": "observation",
        "description": "The observation showing the post-cleanup state of the affected resources."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies artifacts created by the agent's own verification or test activity and states that they must be removed or reset to an initial state.",
      "The cleanup actions delete, reset, or empty those identified artifacts.",
      "The state observation shows the affected resources emptied or matching the intended initial configuration."
    ],
    "exclusion_conditions": [
      "No artifacts were created by the agent's own verification activity, so there is nothing to restore.",
      "The cleanup leaves the identified artifacts in place, or the observation shows them still present because the removal failed.",
      "The deletion is part of ordinary construction rather than restoring a state that a later consumer should encounter."
    ]
  },
  {
    "name": "VERIFIES_RUNTIME_SERVICE_STATE",
    "definition": "An inspection action queries the actual runtime state of deployed components or services, such as running processes, listening sockets, or an exercised endpoint, and the observation shows the intended components or services active at the intended endpoints.",
    "parameters": [
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The tool invocation that queries the running state of the deployed components or services."
      },
      {
        "name": "runtime_observation",
        "type": "observation",
        "description": "The tool result listing processes, listening addresses, or endpoint responses that reveal the components' or services' actual runtime state."
      }
    ],
    "assertion_conditions": [
      "The action queries the actual running state of the components or services (processes, sockets, or an exercised endpoint) rather than only the content of their configuration files.",
      "The observation reports the intended components or services present and active, with the expected endpoints or listening addresses visible."
    ],
    "exclusion_conditions": [
      "The action modifies configuration or starts services instead of inspecting runtime state.",
      "The observation only shows configuration syntax validity without any evidence of running state.",
      "The observation shows the component or service absent or not listening on the intended endpoint.",
      "The observation concerns a resource unrelated to the deployed components or services."
    ]
  },
  {
    "name": "ADDS_AVAILABILITY_SAFEGUARD",
    "definition": "The agent installs a recovery mechanism that restores a component's availability when it is later found stopped, motivated by anticipated future interruptions or restarts rather than by the needs of the immediate request.",
    "parameters": [
      {
        "name": "safeguard_reasoning",
        "type": "reasoning",
        "description": "Reasoning that motivates the extra recovery mechanism as protection against future interruptions or restarts."
      },
      {
        "name": "safeguard_action",
        "type": "action",
        "description": "The tool invocation that creates or installs the recovery mechanism."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the addition as protection against a future interruption, restart, or unavailability rather than as a step needed for the current request to work.",
      "The action creates or installs a mechanism that checks whether the component is present and restarts or restores it when absent.",
      "The mechanism is designed to be safe to invoke repeatedly, so it can act as an automatic safeguard."
    ],
    "exclusion_conditions": [
      "The action is ordinary service startup required for the current request to work at all.",
